using Kunling.RobotClient.Core.Abstractions;using Kunling.RobotClient.Core.Models;using Kunling.RobotClient.Devices.Simulation;
namespace Kunling.RobotClient.Devices.Door;
[DeviceModel("SimulatedRobotDoor")]
public sealed class SimulatedRobotDoor(SimulationState state,SimulationOptions options):IDoor{public Task<DeviceResult<DoorStatus>> OpenAsync(DoorRequest r,CancellationToken ct)=>Set(r,true,ct);public Task<DeviceResult<DoorStatus>> CloseAsync(DoorRequest r,CancellationToken ct)=>Set(r,false,ct);public Task<DeviceResult<DoorStatus>> GetStatusAsync(DoorRequest r,CancellationToken ct){ct.ThrowIfCancellationRequested();lock(state.Sync){var opened=state.Doors.GetValueOrDefault(r.DoorId);options.WriteLog("DOOR:SIM_DOOR","STATUS",$"doorId={r.DoorId} opened={opened}");return Task.FromResult(DeviceResult<DoorStatus>.Ok(new(true,opened)));}}private async Task<DeviceResult<DoorStatus>> Set(DoorRequest r,bool open,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.DoorId)){options.WriteLog("DOOR:SIM_DOOR",open?"OPEN":"CLOSE","参数错误：doorId 不能为空");return DeviceResult<DoorStatus>.Fail(new(4000,"doorId 不能为空。"));}var action=open?"OPEN":"CLOSE";options.WriteLog("DOOR:SIM_DOOR",action,$"doorId={r.DoorId} 开始");await Task.Delay(options.ActionDelayMs,ct);lock(state.Sync)state.Doors[r.DoorId]=open;options.WriteLog("DOOR:SIM_DOOR",action,$"doorId={r.DoorId} 完成");return DeviceResult<DoorStatus>.Ok(new(true,open));}}
